/**
 * mock rhachet-brains-test package for acceptance tests
 * provides claude-code adapter only
 *
 * .note = mirrors the real adapter's contract: it reads and writes the brain dir's
 *   `settings.of.repo.json` by name, whole, via temp + rename — never `settings.json`, which
 *   is the grove arrow to the human's home settings. a legacy REAL `settings.json` is read
 *   while no `settings.of.repo.json` exists
 * .note = each hook is one entry in the real claude shape, `{ matcher, hooks: [{ type,
 *   command, timeout, author }] }`, so rhachet's per-actor narrow (by inner `author`) reads it
 */

const fs = require('fs');
const path = require('path');

const getConfigPath = (repoPath) => path.join(repoPath, '.claude', 'settings.of.repo.json');
const getLegacyPath = (repoPath) => path.join(repoPath, '.claude', 'settings.json');

const readConfig = (repoPath) => {
  const configPath = getConfigPath(repoPath);
  if (fs.existsSync(configPath)) return JSON.parse(fs.readFileSync(configPath, 'utf-8'));
  const legacyPath = getLegacyPath(repoPath);
  const legacyStat = fs.lstatSync(legacyPath, { throwIfNoEntry: false });
  if (legacyStat && legacyStat.isFile()) return JSON.parse(fs.readFileSync(legacyPath, 'utf-8'));
  return { hooks: {} };
};

const writeConfig = (repoPath, config) => {
  const configPath = getConfigPath(repoPath);
  fs.mkdirSync(path.dirname(configPath), { recursive: true });
  const tempPath = `${configPath}.${process.pid}.tmp`;
  fs.writeFileSync(tempPath, JSON.stringify(config, null, 2), 'utf-8');
  fs.renameSync(tempPath, configPath);
};

const eventMap = { onBoot: 'SessionStart', onTool: 'PreToolUse', onStop: 'Stop' };
const toClaudeEvent = (e) => eventMap[e] || e;
const toRhachetEvent = (e) => Object.entries(eventMap).find(([, v]) => v === e)?.[0] || e;

const asEntry = (hook) => ({
  matcher: '*',
  hooks: [{ type: 'command', command: hook.command, timeout: hook.timeout, author: hook.author }],
});
// a legacy flat entry `{ matcher: <author>, command }` reads as one hook, so a seeded
// prior config is still found and can be deleted
const asInnerHooks = (entry) =>
  Array.isArray(entry.hooks)
    ? entry.hooks
    : [{ command: entry.command, timeout: entry.timeout, author: entry.matcher }];
const isMatch = (entry, { author, command }) =>
  asInnerHooks(entry).some((h) => h.command === command && h.author === author);
const asHooks = (claudeEvent, entry) =>
  asInnerHooks(entry).map((h) => ({
    author: h.author,
    event: toRhachetEvent(claudeEvent),
    command: h.command,
    timeout: h.timeout || '30s',
  }));

const getBrainHooks = ({ brain, repoPath }) => {
  if (brain !== 'claude-code' && brain !== 'anthropic/claude/code') return null;

  return {
    slug: 'claude-code',
    dao: {
      get: {
        one: async ({ by }) => {
          const config = readConfig(repoPath);
          const claudeEvent = toClaudeEvent(by.unique.event);
          const entries = config.hooks?.[claudeEvent] || [];
          const found = entries
            .flatMap((entry) => asHooks(claudeEvent, entry))
            .find((h) => h.command === by.unique.command && h.author === by.unique.author);
          return found || null;
        },
        all: async (input) => {
          const config = readConfig(repoPath);
          // support both by.author and by.filter.author for filter
          const by = input?.by;
          const authorFilter = by?.filter?.author ?? by?.author;
          return Object.entries(config.hooks || {})
            .flatMap(([claudeEvent, entries]) => entries.flatMap((entry) => asHooks(claudeEvent, entry)))
            .filter((h) => !authorFilter || h.author === authorFilter);
        },
      },
      set: {
        findsert: async ({ hook }) => {
          const config = readConfig(repoPath);
          const claudeEvent = toClaudeEvent(hook.event);
          if (!config.hooks) config.hooks = {};
          if (!config.hooks[claudeEvent]) config.hooks[claudeEvent] = [];
          if (config.hooks[claudeEvent].some((entry) => isMatch(entry, hook))) return hook;
          config.hooks[claudeEvent].push(asEntry(hook));
          writeConfig(repoPath, config);
          return hook;
        },
        upsert: async ({ hook }) => {
          const config = readConfig(repoPath);
          const claudeEvent = toClaudeEvent(hook.event);
          if (!config.hooks) config.hooks = {};
          if (!config.hooks[claudeEvent]) config.hooks[claudeEvent] = [];
          const idx = config.hooks[claudeEvent].findIndex((entry) => isMatch(entry, hook));
          if (idx >= 0) config.hooks[claudeEvent][idx] = asEntry(hook);
          else config.hooks[claudeEvent].push(asEntry(hook));
          writeConfig(repoPath, config);
          return hook;
        },
      },
      del: async ({ by }) => {
        const config = readConfig(repoPath);
        const claudeEvent = toClaudeEvent(by.unique.event);
        if (!config.hooks?.[claudeEvent]) return;
        config.hooks[claudeEvent] = config.hooks[claudeEvent].filter((entry) => !isMatch(entry, by.unique));
        if (config.hooks[claudeEvent].length === 0) delete config.hooks[claudeEvent];
        writeConfig(repoPath, config);
      },
    },
  };
};

module.exports = { getBrainHooks };
